import { DataTypes } from "sequelize";
import { sequelize } from "../db/sequelize.js";
import crypto from "crypto";

const ChatRoom = sequelize.define('ChatRoom', {
    id: {
        type: DataTypes.UUID,
        defaultValue: DataTypes.UUIDV4,
        primaryKey: true,
    },
    name: {
        type: DataTypes.STRING,
        allowNull: false,
    },
    // the code is autogenerated when the room is created, and is used to join the room
    inviteCode: {
        type: DataTypes.STRING,
        allowNull: false,
        unique: true,
    },
}, {
    tableName: 'chatroom',
    timestamps: true,
    hooks: {
        // when the chatroom is created, generate an invite code
        beforeValidate: (chatroom, options) => {
            chatroom.inviteCode = crypto.randomBytes(3).toString('hex').toUpperCase();
        },
    }
});

export default ChatRoom;